patches.new_text:
func _on_Area2D_area_exited(area: Area2D) -> void :
				if area.get_parent().is_in_group("player"):
								print("PLAYER FOUND")
								nearby = false
								if not mouse_hover:
												remove_context()
				_update_visual_state()

func _ensure_backer_style() -> void :
				if backer_style != null:
								return
				backer_style = StyleBoxFlat.new()
				backer_style.corner_radius_top_left = 4
				backer_style.corner_radius_top_right = 4
				backer_style.corner_radius_bottom_right = 4
				backer_style.corner_radius_bottom_left = 4
				backer_style.content_margin_left = 8.0
				backer_style.content_margin_top = 4.0
				backer_style.content_margin_right = 8.0
				backer_style.content_margin_bottom = 4.0

func _update_visual_state() -> void :
				_ensure_backer_style()
				var label = $Node2D / VBoxContainer / HBoxContainer / Label
				if disabled:
								label_text_alpha = 0.85
								label_backer_alpha = 0.0
								label_accent_alpha = 0.0
				elif mouse_hover:
								label_text_alpha = 1.0
								label_backer_alpha = 0.62
								label_accent_alpha = 0.85
				elif nearby:
								label_text_alpha = 1.0
								label_backer_alpha = 0.45
								label_accent_alpha = 0.0
				else:
								label_text_alpha = 0.85
								label_backer_alpha = 0.0
								label_accent_alpha = 0.0
				label.modulate = Color(1, 1, 1, label_text_alpha)
				if disabled:
								modulate = Color(0.384314, 0.427451, 0.470588, 0.55)
				else:
								modulate = Color(1, 1, 1, 1)
				update()

func _draw() -> void :
				_draw_label_backer()
				if disabled:
								return
				_draw_ground_shadow()
				if mouse_hover:
								if can_interact():
												draw_circle(Vector2.ZERO, 26.0, Color(0.47451, 0.85098, 0.545098, 0.10))
												draw_arc(Vector2.ZERO, 22.0, 0.0, TAU, 32, Color(0.47451, 0.85098, 0.545098, 0.85), 2.0, true)
												draw_circle(Vector2(0, -20), 2.5, Color(0.47451, 0.85098, 0.545098, 0.85))
								else:
												draw_circle(Vector2.ZERO, 26.0, Color(0.47451, 0.85098, 0.545098, 0.14))
												draw_arc(Vector2.ZERO, 22.0, 0.0, TAU, 32, Color(0.25098, 0.32549, 0.396078, 0.75), 2.0, true)
				elif nearby:
								draw_circle(Vector2.ZERO, 26.0, Color(0.47451, 0.85098, 0.545098, 0.08))

func can_interact() -> bool:
				return not disabled

func _draw_ground_shadow() -> void :
				if has_node("Shadow"):
								return
				draw_set_transform(Vector2(0, 16), 0.0, Vector2(1, 6.0 / 18.0))
				draw_circle(Vector2(0, 0), 18.0, Color(0.0352941, 0.0470588, 0.0627451, 0.35))
				draw_set_transform(Vector2.ZERO, 0.0, Vector2.ONE)

func _draw_label_backer() -> void :
				if label_backer_alpha <= 0.0 and label_accent_alpha <= 0.0:
								return
				_ensure_backer_style()
				var label = $Node2D / VBoxContainer / HBoxContainer / Label
				var font = label.get_font("font")
				var tsize = font.get_string_size(label.text)
				var w = tsize.x + 16.0
				var h = tsize.y + 8.0
				var rect_center = label.get_global_rect().position + label.get_global_rect().size * 0.5
				var local_pos = to_local(rect_center) - Vector2(w, h) * 0.5
				backer_style.bg_color = Color(0.0470588, 0.0627451, 0.0823529, label_backer_alpha)
				backer_style.border_color = Color(0.47451, 0.85098, 0.545098, label_accent_alpha)
				if label_accent_alpha > 0.0:
								backer_style.border_width_bottom = 2
				else:
								backer_style.border_width_bottom = 0
				draw_style_box(backer_style, Rect2(local_pos, Vector2(w, h)))

